import { createReducer, on } from "@ngrx/store";
import * as CartActions from "./cart.actions";
export const initialState = {
  cartDetails: [],
  loading: false,
  error: null
};
export const cartReducer = createReducer(initialState, on(CartActions.loadCart, state => ({
  ...state,
  loading: true
})), on(CartActions.loadCartSuccess, (state, {
  cartDetails
}) => ({
  ...state,
  loading: false,
  cartDetails,
  size: cartDetails.length
})), on(CartActions.loadCartFailure, (state, {
  error
}) => ({
  ...state,
  loading: false,
  size: 0,
  error
})), on(CartActions.deleteCartItem, state => ({
  ...state,
  loading: true
})), on(CartActions.deleteCartItemSuccess, (state, {
  cartId
}) => ({
  ...state,
  loading: false,
  cartDetails: state.cartDetails.filter(item => item.id !== cartId)
})), on(CartActions.deleteCartItemFailure, (state, {
  error
}) => ({
  ...state,
  loading: false,
  error,
  size: 0
})));
